mapper.select:
/*
	 SQL ID : UsrDeptCdDAO.select
	 설  명 : 학과(부서) 정보 조회
*/

	AND A.DEPT_ID = #{deptId}

		AND ORG_ID = #{orgId}

/* SQL ID : UsrDeptCdDAO.list 설 명 : 학과(부서) 목록 조회 */
AND A.ORG_ID = #{orgId}
AND ( LOWER(A.DEPT_ID) LIKE '%' || LOWER(#{searchValue})|| '%' OR LOWER(A.DEPTNM) LIKE '%'|| LOWER(#{searchValue}) || '%' OR LOWER(A.DEPT_ENNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )
ORDER BY A.DEPTNM DESC

/*	설  명 : 기관별부서목록조회		*/		


	AND A.ORG_ID = #{orgId}


	AND (
			LOWER(A.DEPT_ID) LIKE '%' || LOWER(#{searchValue}) || '%'
		 OR LOWER(A.DEPTNM)   LIKE '%'|| LOWER(#{searchValue}) || '%'
		 OR LOWER(A.DEPT_ENNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
	)

ORDER BY A.DEPTNM DESC

/* SQL ID : UsrDeptCdDAO.profDeptList 설 명 : 과목 담당자(교수,튜터 등)의 담당 학과(부서) 목록 조회 */ SELECT DISTINCT DEPT.DEPT_ID , DEPT.DEPTNM FROM TB_LMS_SBJCT_ADM PRF JOIN TB_LMS_SBJCT SBJ ON PRF.SBJCT_ID = SBJ.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT SMSTR ON SBJ.SMSTR_CHRT_ID = SMSTR.SMSTR_CHRT_ID JOIN TB_LMS_DEPT DEPT ON SBJ.DEPT_ID = DEPT.DEPT_ID JOIN TB_LMS_ORG ORG ON DEPT.ORG_ID = ORG.ORG_ID WHERE 1=1 AND PRF.USER_ID IN ( SELECT USER_ID FROM TB_LMS_USER X WHERE X.USER_RPRS_ID = #{rprsId} )
AND ORG.ORG_ID = #{orgId}
AND SMSTR.DGRS_YR = #{dgrsYr}
AND SMSTR.DGRS_SMSTR_CHRT = #{dgrsSmstrChrt}
AND SBJ.USEYN = 'Y' AND SBJ.DELYN = 'N' ORDER BY DEPT.DEPTNM

/* SQL ID : UsrDeptCdDAO.stdntDeptList 설 명 : 학생이 수강하는 학과(부서) 목록 조회 */ SELECT DISTINCT DEPT.DEPT_ID , DEPT.DEPTNM FROM TB_LMS_ATNDLC STD JOIN TB_LMS_SBJCT SBJ ON STD.SBJCT_ID = SBJ.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT SMSTR ON SBJ.SMSTR_CHRT_ID = SMSTR.SMSTR_CHRT_ID JOIN TB_LMS_DEPT DEPT ON SBJ.DEPT_ID = DEPT.DEPT_ID JOIN TB_LMS_ORG ORG ON DEPT.ORG_ID = ORG.ORG_ID WHERE 1=1 AND STD.USER_ID IN ( SELECT USER_ID FROM TB_LMS_USER X WHERE X.USER_RPRS_ID = #{rprsId} )
AND ORG.ORG_ID = #{orgId}
AND SMSTR.DGRS_YR = #{dgrsYr}
AND SMSTR.DGRS_SMSTR_CHRT = #{dgrsSmstrChrt}
AND STD.ATNDLC_STSCD = 'APPROVE' AND SBJ.USEYN = 'Y' AND SBJ.DELYN = 'N' ORDER BY DEPT.DEPTNM

/*
	SQL ID : count
	설  명 : 부서 정보의 전체 카운트
*/
SELECT COUNT(*) FROM (


		AND A.ORG_ID = #{orgId}


		AND (
				LOWER(A.DEPT_ID) LIKE CONCAT('%', LOWER(#{searchValue}), '%')
			 OR  LOWER(A.DEPTNM) LIKE CONCAT('%', LOWER(#{searchValue}), '%')
		)

	 ORDER BY A.DEPT_ID_ODR DESC
) T

/*
	 SQL ID : UsrDeptCdDAO.listPageing
	 설  명 : 학과(부서) 목록 조회 페이징
*/



		AND A.ORG_ID = #{orgId}


		AND (
				  LOWER(A.DEPT_ID) LIKE CONCAT('%', LOWER(#{searchValue}), '%')
			 OR LOWER(A.DEPTNM) LIKE CONCAT('%', LOWER(#{searchValue}), '%')
		)

ORDER BY A.DEPT_ID_ODR DESC

mapper.insert:
	/*
		 SQL ID : UsrDeptCdDAO.insert
		 설  명 : 학과(부서) 등록
 	*/
	INSERT INTO TB_HOME_USER_DEPT_ID (
		  DEPT_ID
		, ORG_ID
		, DEPTNM
		, DEPT_NM_EN
		, PAR_DEPT_ID
		, RGTR_ID
		, FRST_INQ_DTTM
	) VALUES (
		  #{deptId}
		, #{orgId}
		, #{deptNm}
		, #{deptEnnm}
		, #{upDeptId}
		, #{rgtrId}
		, FN_DTTM()
	)

mapper.update:
/*
	 SQL ID : UsrDeptCdDAO.update
	 설  명 : 학과(부서) 수정
*/
UPDATE TB_HOME_USER_DEPT_ID
      SET DEPT_ID = #{deptId}
         , DEPTNM = #{deptNm}

         , DEPT_NM_EN = #{deptEnnm}

         , PAR_DEPT_ID = #{upDeptId}
         , MDFR_ID = #{mdfrId}
         , MOD_DTTM = FN_DTTM()
 WHERE DEPT_ID = #{deptId}

mapper.delete:
/*
	 SQL ID : UsrDeptCdDAO.delete
	 설  명 : 학과(부서) 삭제
*/
DELETE FROM TB_HOME_USER_DEPT_ID
 WHERE DEPT_ID = #{deptId}

mapper.update:
/*
	 SQL ID : UsrDeptCdDAO.updateUseYn
	 설  명 : 학과(부서) > 사용여부 변경
*/

	UPDATE TB_HOME_USER_DEPT_ID
	   SET USEYN  = #{useYn}
	     , MDFR_ID  = #{mdfrId}
	     , MOD_DTTM  = FN_DTTM()
	 WHERE DEPT_ID = #{deptId}
